139	+import type { State, ToolView } from "./types.ts";
140	+import { toToolView } from "./tool-view.ts";
141	+
142	+export type BorrowResult =
143	+  | { ok: true; tool: ToolView }
144	+  | {
145	+      ok: false;
146	+      error: { code: "VALIDATION_ERROR" | "TOOL_NOT_FOUND" | "ALREADY_BORROWED"; message: string };
147	+    };
