149	+export function borrowTool(
150	+  state: State,
151	+  toolId: string,
152	+  borrower: string | undefined,
153	+  now: Date,
154	+): { state: State; result: BorrowResult } {
155	+  const trimmedBorrower = typeof borrower === "string" ? borrower.trim() : "";
156	+  if (trimmedBorrower.length === 0) {
157	+    return {
158	+      state,
159	+      result: {
160	+        ok: false,
161	+        error: { code: "VALIDATION_ERROR", message: "Bitte einen Namen angeben." },
162	+      },
163	+    };
164	+  }
165	+
166	+  const tool = state.tools.find((candidate) => candidate.id === toolId);
167	+  if (tool === undefined) {
168	+    return {
169	+      state,
170	+      result: {
171	+        ok: false,
172	+        error: { code: "TOOL_NOT_FOUND", message: "Werkzeug nicht gefunden." },
173	+      },
174	+    };
175	+  }
176	+
177	+  const existingLoan = state.loans.find((candidate) => candidate.toolId === toolId);
178	+  if (existingLoan !== undefined) {
179	+    return {
180	+      state,
181	+      result: {
182	+        ok: false,
183	+        error: { code: "ALREADY_BORROWED", message: "Dieses Werkzeug ist bereits ausgeliehen." },
184	+      },
185	+    };
186	+  }
187	+
188	+  const newLoan = { toolId, borrower: trimmedBorrower, borrowedAt: now.toISOString() };
189	+  const nextState: State = { tools: state.tools, loans: [...state.loans, newLoan] };
190	+  return { state: nextState, result: { ok: true, tool: toToolView(tool, nextState.loans) } };
191	+}
